func (c *CourseStockRepo) FindMultiByCondition(ctx context.Context, conditionReq *condition.Req) ([]*yanxue_model.CourseStock, *condition.Reply, error) {
	result := make([]*yanxue_model.CourseStock, 0)
	conditionReply := &condition.Reply{}
	var total int64
	whereExpressions, orderExpressions, err := conditionReq.ConvertToGormExpression(yanxue_model.CourseStock{})
	if err != nil {
		return result, conditionReply, err
	}
	if conditionReq.Page != 0 && conditionReq.PageSize != 0 {
		err = c.db.WithContext(ctx).Model(&yanxue_model.CourseStock{}).Clauses(whereExpressions...).Count(&total).Error
		if err != nil {
			return result, conditionReply, err
		}
		if total == 0 {
			return result, conditionReply, nil
		}
		conditionReply, err = conditionReq.ConvertToPage(int32(total))
		if err != nil {
			return result, conditionReply, err
		}
		query := c.db.WithContext(ctx).Model(&yanxue_model.CourseStock{}).Clauses(whereExpressions...).Clauses(orderExpressions...)
		if conditionReply.Page != 0 && conditionReply.PageSize != 0 {
			query = query.Offset(int((conditionReply.Page - 1) * conditionReply.PageSize))
			query = query.Limit(int(conditionReply.PageSize))
		}
		err = query.Find(&result).Error
		if err != nil {
			return result, conditionReply, err
		}
	} else {
		err = c.db.WithContext(ctx).Model(&yanxue_model.CourseStock{}).Clauses(whereExpressions...).Clauses(orderExpressions...).Find(&result).Error
		if err != nil {
			return result, conditionReply, err
		}
		conditionReply.Total = int32(len(result))
	}
	return result, conditionReply, err
}

// FindMultiCacheByCondition 自定义查询数据(通用),并设置缓存
// 非万能查询方法,缓存命中率低,请评估后谨慎使用
func (c *CourseStockRepo) FindMultiCacheByCondition(ctx context.Context, conditionReq *condition.Req) ([]*yanxue_model.CourseStock, *condition.Reply, error) {
	type Tmp struct {
		Result         []*yanxue_model.CourseStock
		ConditionReply *condition.Reply
	}
	tmp := Tmp{
		Result:         make([]*yanxue_model.CourseStock, 0),
		ConditionReply: &condition.Reply{},
	}
	cacheKey := c.cache.Key(CacheCourseStockByConditionPrefix)
	cacheField := conditionReq.ConvertToCacheField()
	cacheValue, err := c.cache.FetchHash2(ctx, cacheKey, cacheField, func() (string, error) {
		result, conditionReply, err := c.FindMultiByCondition(ctx, conditionReq)
		if err != nil {
			return "", err
		}
		tmp.Result = result
		tmp.ConditionReply = conditionReply
		marshal, err := c.encoding.Marshal(tmp)
		if err != nil {
			return "", err
		}
		return string(marshal), nil
	}, c.cache.TTL())
	if err != nil {
		return tmp.Result, tmp.ConditionReply, err
	}
	if cacheValue != "" {
		err = c.encoding.Unmarshal([]byte(cacheValue), &tmp)
		if err != nil {
			return tmp.Result, tmp.ConditionReply, err
		}
	}
	return tmp.Result, tmp.ConditionReply, nil
}

