// DeleteUniqueIndexCache 删除索引存在的缓存
func (c *CourseStockRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.CourseStock) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, c.cache.Key(CacheCourseStockByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[c.cache.Key(CacheCourseStockByIDPrefix, item.ID)] = struct{}{}
			KeyMap[c.cache.Key(CacheCourseStockByCourseIDDatePeriodPrefix, item.CourseID, item.Date, item.Period)] = struct{}{}
			KeyMap[c.cache.Key(CacheCourseStockByCourseIDDatePrefix, item.CourseID, item.Date)] = struct{}{}
			KeyMap[c.cache.Key(CacheCourseStockByCourseIDPrefix, item.CourseID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := c.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
